int a = 1;
int b = INT_MAX;
int result;

// Using compiler built-ins (GCC/Clang/ICC)
// Returns true on overflow/underflow

// Addition check
if (__builtin_add_overflow(a, b, &result)) {
    // Overflow detected. Handle error.
    // 'result' holds the wrapped value (usually)
}

// Subtraction check
if (__builtin_sub_overflow(a, b, &result)) {
    // Underflow/Overflow detected.
}

// Multiplication check
if (__builtin_mul_overflow(a, b, &result)) {
    // Overflow detected.
}

// For truly safe, portable math, use wider types:
long long safe_sum = (long long)a + b;
